+    const int column = frame->GetColumn();
+    if (function_name.length() == 0) {
+      result += SPrintF("    at %s:%d:%d\n", script_name, line, column);
+    } else {
+      result += SPrintF(
+          "    at %s (%s:%d:%d)\n", function_name, script_name, line, column);
+    }
+  }
+  return result;
